const { expect } = require('chai');
const hre = require('hardhat');
const fs = require('fs');
const path = require('path');

// §8.1: prove castVoteAnonymous across the WHOLE lean B.2 family (Boolean/Average/Median/
// Plurality) with REAL Groth16 proofs (test/fixtures/anon-proofs.json, generated by the
// backend's zkVoteService), plus the transparent-path retirement flag. The composition is
// proof-system-agnostic — the verifier swaps Groth16→STARK at the dev cutover, boxes unchanged.
describe('BaseRuleBallotBox.castVoteAnonymous — lean family (real Groth16 proofs)', () => {
  const fx = JSON.parse(fs.readFileSync(path.join(__dirname, 'fixtures', 'anon-proofs.json'), 'utf8'));
  const Z = hre.ethers.ZeroAddress;
  const abi = hre.ethers.AbiCoder.defaultAbiCoder();
  let deployer, av;

  const unpack = (entry) => {
    expect(entry.offchainOk).to.equal(true);
    const { a, b, c, publicSignals } = entry.calldata;
    const [nullifierHash, merkleRoot, externalNullifier, voteChoice, prevNullifierHash] = publicSignals;
    return { a, b, c, nullifierHash, merkleRoot, externalNullifier, voteChoice, prevNullifierHash };
  };

  const deployBox = async (name, quorumBps = 5000) =>
    (await hre.ethers.getContractFactory(name))
      .deploy(deployer.address /* voteToken placeholder */, 1, deployer.address, Z, quorumBps, Z)
      .then((x) => x.waitForDeployment().then(() => x));

  const wire = async (box, ruleKey, config, p) => {
    await box.registerRule(ruleKey, hre.ethers.id('meta'), config);
    await box.setAnonymousVerifier(await av.getAddress());
    await box.setRuleExternalNullifier(ruleKey, p.externalNullifier);
    await av.registerBallotRoot(p.externalNullifier, p.merkleRoot);
  };

  const castAnon = (box, ruleKey, p) =>
    box.castVoteAnonymous(ruleKey, p.a, p.b, p.c, p.merkleRoot, [Number(p.voteChoice)], p.nullifierHash, p.prevNullifierHash);

  beforeEach(async () => {
    [deployer] = await hre.ethers.getSigners();
    const vv = await (await hre.ethers.getContractFactory('VoteVerifier')).deploy();
    await vv.waitForDeployment();
    av = await (await hre.ethers.getContractFactory('AnonymousVoteVerifier')).deploy(await vv.getAddress(), deployer.address);
    await av.waitForDeployment();
  });

  it('Boolean — anonymous support → 100% bps, nullifier spent, replay reverts', async () => {
    const box = await deployBox('BooleanRuleBallotBox');
    const rk = hre.ethers.id('b'); const p = unpack(fx.boolean);
    await wire(box, rk, '0x', p);
    await castAnon(box, rk, p);
    const [value, total, quorumMet] = await box.currentResult(rk);
    expect(total).to.equal(1n); expect(value).to.equal(10000n); expect(quorumMet).to.equal(true);
    expect(await av.isNullifierSpent(p.externalNullifier, p.nullifierHash)).to.equal(true);
    await expect(castAnon(box, rk, p)).to.be.revertedWith('AnonymousVoteVerifier: nullifier already spent');
  });

  it('Average — anonymous value 50 → 50', async () => {
    const box = await deployBox('AverageRuleBallotBox');
    const rk = hre.ethers.id('a'); const p = unpack(fx.value);
    await wire(box, rk, abi.encode(['uint16'], [100]), p);
    await castAnon(box, rk, p);
    const [value, total] = await box.currentResult(rk);
    expect(total).to.equal(1n); expect(value).to.equal(50n);
  });

  it('Median — anonymous value 50 → 50', async () => {
    const box = await deployBox('MedianRuleBallotBox');
    const rk = hre.ethers.id('m'); const p = unpack(fx.value);
    await wire(box, rk, abi.encode(['uint16'], [100]), p);
    await castAnon(box, rk, p);
    const [value, total] = await box.currentResult(rk);
    expect(total).to.equal(1n); expect(value).to.equal(50n);
  });

  it('Plurality — anonymous choice 2 → winning choice 2', async () => {
    const box = await deployBox('PluralityRuleBallotBox');
    const rk = hre.ethers.id('p'); const p = unpack(fx.plurality);
    await wire(box, rk, abi.encode(['uint16'], [5]), p);
    await castAnon(box, rk, p);
    const [value, total] = await box.currentResult(rk);
    expect(total).to.equal(1n); expect(value).to.equal(2n);
  });

  it('transparent voting can be retired (governance flag)', async () => {
    const box = await deployBox('BooleanRuleBallotBox');
    const rk = hre.ethers.id('b');
    await box.registerRule(rk, hre.ethers.id('meta'), '0x');
    await box.setTransparentVotingDisabled(true);
    // the flag check is first in castVote → reverts before touching voteToken
    await expect(box.castVote(rk, 1, [1])).to.be.revertedWith('RuleBox: transparent voting retired');
  });
});
